const webhookItem = $('Webhook WhatsApp').first().json;
const data = webhookItem.body.data;

if (data.key?.fromMe === true) {
  return [];
}

const msgTimestamp = data.messageTimestamp;
const nowSeconds = Math.floor(Date.now() / 1000);
const MAX_AGE_SECONDS = 600;
if (msgTimestamp && (nowSeconds - msgTimestamp) > MAX_AGE_SECONDS) {
  return [];
}

const audio = data.message.audioMessage;
const texto = data.message.conversation || '';
const numeroRemetente = data.key.remoteJid;
const nomeContato = data.pushName || 'Desconhecido';

// --- Carrega usuários da planilha e identifica o nível de quem enviou ---
const usuarios = $input.all().map(i => i.json);
const numeroRemetenteLimpo = numeroRemetente.replace('@s.whatsapp.net', '');
const usuarioAtual = usuarios.find(u => String(u.Numero) === numeroRemetenteLimpo);
const nivelAtual = usuarioAtual ? usuarioAtual.Nivel : 'Desconhecido';
// --- BLOQUEIO: só usuários cadastrados podem usar o bot ---
if (nivelAtual === 'Desconhecido') {
  return [{
    json: {
      tipo: 'nao_cadastrado',
      numero: numeroRemetente,
      nomeContato,
      textoResposta: '❌ Você ainda não está cadastrado no LabFlow. Peça a um administrador para te cadastrar.'
    }
  }];
}
// Sinaliza se o nome do WhatsApp de quem mandou mudou (ou nunca foi
// preenchido) em relação ao que já está salvo na USUARIOS — só pra quem
// já é cadastrado (nunca cria cadastro novo por essa via).
const sincronizarNome = !!(usuarioAtual && usuarioAtual.Nome !== nomeContato);

// Toda resposta passa por aqui, pra sempre levar junto os dados de
// sincronização de nome sem precisar repetir em cada bloco abaixo.
function output(json) {
  return [{
    json: {
      ...json,
      _sincronizarNome: sincronizarNome,
      _numeroRemetenteLimpo: numeroRemetenteLimpo,
      _nomeContatoAtual: nomeContato
    }
  }];
}
// --- ÁUDIO: o Gemini transcreve e o texto volta reenviado (labflowAudio); até 1 minuto ---
if (audio && !texto) {
  if ((Number(audio.seconds) || 0) > 60) {
    return output({ tipo: 'erro_coleta', numero: numeroRemetente, nomeContato,
      textoResposta: '🎤 Áudio muito longo (máximo 1 minuto). Mande um comando por áudio.' });
  }
  return output({ tipo: 'audio_transcrever', mensagemId: data.key.id, segundos: Number(audio.seconds) || 0,
    numero: numeroRemetente, nomeContato });
}
// Texto transcrito de um áudio: vai direto para a IA, que sempre pede "sim" antes de gravar (a regex
// gravaria alguns comandos sem perguntar, e a transcrição pode errar). "sim" e "não" falados seguem normais.
if (webhookItem.body.labflowAudio === true && !/^(sim|n[aã]o)[.!]?$/i.test(texto.trim())) {
  return output({ tipo: 'interpretar_ia', mensagem_original: texto, audio: true,
    hoje: new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' }),
    numero: numeroRemetente, nomeContato, nivelAtual });
}
// Calcula as N linhas de análise (CT, BL, WORT) para um tanque, a partir
// da data em que o frasco (Normal ou Stress) foi analisado.
function calcularAnalises(dataAnaliseStr, idColeta, tanque, tipoFrasco, tipoTanque, navio) {
  const [dia, mes, ano] = dataAnaliseStr.split('/').map(Number);
  const dataBase = new Date(ano, mes - 1, dia);

  const formatarData = (d) =>
    `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')}/${d.getFullYear()}`;

  const somarHoras = (dataBase, horas) => {
    const d = new Date(dataBase);
    d.setHours(d.getHours() + horas);
    return d;
  };

  // Config: { pre: horas ou null, final: horas }
  const PRAZOS = {
    CT:   { pre: null, final: 48 },
    BL:   { pre: 72,   final: 120 },
    WORT: { pre: 120,  final: 240 }
  };

  // Cada linha: { subAnalise, metodo }
  const LINHAS = [
    { subAnalise: 'CT',   metodo: 'Profundidade' },
    { subAnalise: 'BL',   metodo: 'Profundidade' },
    { subAnalise: 'WORT', metodo: 'Profundidade' },
    { subAnalise: 'WORT', metodo: 'Superficie' }
  ];

  return LINHAS.map(({ subAnalise, metodo }, idx) => {
    const prazo = PRAZOS[subAnalise];
    const dataPreLeitura = prazo.pre !== null
      ? formatarData(somarHoras(dataBase, prazo.pre))
      : '';
    const dataLeituraFinal = formatarData(somarHoras(dataBase, prazo.final));
    const status = prazo.pre !== null
      ? 'Aguardando Pré-Leitura'
      : 'Aguardando Leitura Final';

    return {
      idAnalise: `AN-${idColeta}-${tipoFrasco}-${subAnalise}-${metodo}`.slice(0, 60),
      idColeta,
      tanque,
      tipoTanque,
      navio: navio || '',
      tipoFrasco,
      subAnalise,
      metodo,
      dataAnalise: dataAnaliseStr,
      dataPreLeitura,
      dataLeituraFinal,
      status,
      responsavel: nomeContato
    };
  });
}
// Calcula as 3 datas de drop (D5, D10, D15) a partir da data de coleta
function calcularDrops(dataColetaStr, idColeta, tanque, tipoTanque, navio) {
  const [dia, mes, ano] = dataColetaStr.split('/').map(Number);
  const dataBase = new Date(ano, mes - 1, dia);
  const dias = [5, 10, 15];
  return dias.map(offset => {
    const dataDrop = new Date(dataBase);
    dataDrop.setDate(dataDrop.getDate() + offset);
    const dd = String(dataDrop.getDate()).padStart(2, '0');
    const mm = String(dataDrop.getMonth() + 1).padStart(2, '0');
    const yyyy = dataDrop.getFullYear();
    return {
      idDrop: `DR-${idColeta}-${offset}`,
      idColeta: idColeta,
      tipoTanque: tipoTanque,
      tanque: tanque,
      navio: navio || '',
      diaDrop: `D${offset}`,
      dataPrevista: `${dd}/${mm}/${yyyy}`,
      status: 'Pendente',
      responsavel: nomeContato
    };
  });
}
function calcularArquivo(dataColetaStr, idColeta, tanque, navio) {
  const [dia, mes, ano] = dataColetaStr.split('/').map(Number);
  const dataColeta = new Date(ano, mes - 1, dia);
  const dataDescarte = new Date(dataColeta);
  dataDescarte.setDate(dataDescarte.getDate() + 365);

  const formatarData = (d) =>
    `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')}/${d.getFullYear()}`;

  return {
    id: `AR-${idColeta}`,
    idColeta,
    tanque,
    navio: navio || '',
    dataColeta: dataColetaStr,
    dataDescarte: formatarData(dataDescarte),
    status: 'Arquivado',
    responsavel: nomeContato
  };
}
// --- AJUDA POR TÓPICO: "comandos drops", "consultar análises"... (sem IA) ---
const ajudaBusca = texto.trim().toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[?!.]+$/, '').trim();

const AJUDA_TOPICOS = [
  { chave: 'drops', nomes: /^drops?$/, texto:
    '📖 *Comandos de drops*\n\n' +
    '*Consultar*\n• drops para hoje\n\n' +
    '*Concluir* (marca os drops de hoje como feitos)\n' +
    '• Concluir drops D5 terra\n' +
    '• Concluir drops D10 navio O.SKY 123\n' +
    '• Concluir drops terra\n' +
    '• Concluir drops navio\n\n' +
    'D5, D10 e D15 são as análises de drop. Sem o dia, conclui todos os que vencem hoje.' },
  { chave: 'tanques', nomes: /^(tanques?|coletas?)$/, texto:
    '📖 *Comandos de coleta de tanques*\n\n' +
    '• registrar coleta tanque terra 42,43 data 28/09/2026 (até 8 tanques)\n' +
    '• Coleta navio O.SKY 123 tanques 1C,4P data 28/09/2026 (até 16 tanques)\n\n' +
    'Cada coleta gera as datas de drop (D5, D10, D15) e de descarte.' },
  { chave: 'analises', nomes: /^analises?$/, texto:
    '📖 *Comandos de análise*\n\n' +
    '*Registrar* (normal ou stress)\n' +
    '• Analise normal tanques 44,45 data 29/09/2026\n' +
    '• Analise stress tanques 1C,4P navio O.SKY 123 data 29/09/2026\n\n' +
    '*Consultar o que sai hoje*\n' +
    '• Quais analises de tanques terra saem hoje?\n' +
    '• Quais analises de tanques navio saem hoje?' },
  { chave: 'leituras', nomes: /^leituras?$/, texto:
    '📖 *Comandos de leitura*\n\n' +
    'Conclui as leituras (CT, BL, WORT) que vencem hoje. O bot lista e pergunta *sim* ou *não* antes de gravar.\n' +
    '• Concluir leitura terra\n' +
    '• Concluir final leitura CT normal terra\n' +
    '• Concluir pre leitura BL stress navio O.SKY 123\n' +
    '• Concluir leitura navio\n\n' +
    'Opcionais: pre ou final, CT ou BL ou WORT, normal ou stress.\n\n' +
    '*Placas (triplicata)* — o bot mostra ok / não ok e pergunta *sim*:\n' +
    '• ct do tanque 47 normal 12,8,15\n' +
    '• bl72 do tanque 47 stress 0,1,0\n' +
    '• bl120 do tanque 5 navio O.SKY 123 normal 0,0,2\n' +
    '• wort profundidade 240h do tanque 47 normal 0,0,1 coleta 01/10/2026\n' +
    '0 ou <1 = sem colônia. Leitura acima do limite: o bot pergunta se abre o desvio.\n\n' +
    '*Repetição* (só com desvio aberto): repetição do tanque 47 stress bl120' },
  { chave: 'descarte', nomes: /^(descartes?|bags?|potes?|bags e potes)$/, texto:
    '📖 *Comandos de descarte*\n\n' +
    '• Quais bags posso descartar hoje (tanques de terra)\n' +
    '• Quais potes do navio posso descartar hoje' },
  { chave: 'relatorio', nomes: /^(relatorios?|relatorios? do dia)$/, texto:
    '📖 *Relatório do dia*\n\n' +
    '• relatório do dia tanques terra\n' +
    '• relatório do dia tanques navio\n' +
    '• relatório do dia (os dois blocos)\n' +
    '• leitura do dia finalizada (marca tudo de hoje como lido)\n' +
    '• drop d5 do tanque 45 data 30/09/2026 não ok (abre desvio)\n' +
    '• quais desvios de drops do tanque 45? / quais desvios estão abertos?\n\n' +
    'Mostra o que sai hoje em cada linha do relatório. ✅ = já lido.' },
  { chave: 'cargos', nomes: /^(cargos?|(gerenciar|gerencia)( de)? cargos?|gerencia|usuarios?)$/, texto:
    '📖 *Comandos de cargo* (somente Admin)\n\n' +
    '• trocar cargo de Operador para o número <número com DDD> nome João\n' +
    '• trocar cargo de Consultor para o número <número com DDD>\n\n' +
    'Cargos válidos: Admin, Operador e Consultor.' }
];

const AJUDA_MENU =
  '📖 *Lista de comandos.* Escreva o que procura:\n' +
  '• consultar drops\n' +
  '• consultar tanques\n' +
  '• consultar análises\n' +
  '• consultar leituras\n' +
  '• consultar descarte (bags e potes)\n' +
  '• consultar cargos\n' +
  '• consultar relatório\n\n' +
  'Você também pode escrever livremente. Antes de gravar, o bot mostra como entendeu e pede *sim* ou *não*.';

function acharTopico(nome) {
  return AJUDA_TOPICOS.find(t => t.nomes.test(nome.trim()));
}

const matchAjudaComandos = ajudaBusca.match(/^(?:consultar\s+|ver\s+|lista\s+de\s+)?comandos?(?:\s+(?:para|de|do|da|dos|das|sobre))?(?:\s+(.+))?$/);
const matchAjudaConsultar = ajudaBusca.match(/^consultar\s+(.+)$/);
let respostaAjuda = null;

if (matchAjudaComandos) {
  const pedido = matchAjudaComandos[1];
  const topico = pedido ? acharTopico(pedido) : null;
  respostaAjuda = topico ? topico.texto
    : (pedido ? `❌ Não encontrei comandos para "${pedido}".\n\n` : '') + AJUDA_MENU;
} else if (matchAjudaConsultar && acharTopico(matchAjudaConsultar[1])) {
  respostaAjuda = acharTopico(matchAjudaConsultar[1]).texto;
}

if (respostaAjuda) {
  // Reaproveita a rota de resposta de texto simples (tipo 'erro_ia' -> HTTP Request IA provisorio)
  return output({
    tipo: 'erro_ia',
    numero: numeroRemetente,
    nomeContato,
    textoResposta: respostaAjuda
  });
}
// --- GERENCIAR USUARIO ---
const regexGerenciarUsuario = /(adicionar|trocar|mudar)\s+cargo\s+(?:de\s+)?(\w+)\s+para\s+o?\s*n[uú]mero\s+(\d+)(?:\s+nome\s+(.+))?/i;
const matchGerenciar = texto.match(regexGerenciarUsuario);

if (matchGerenciar) {
  const nivelNovo = matchGerenciar[2];
  const numeroAlvo = matchGerenciar[3];
  const nomeInformado = matchGerenciar[4] ? matchGerenciar[4].trim() : null;

  if (nivelAtual !== 'Admin') {
    return output({
      tipo: 'gerenciar_usuario',
      autorizado: false,
      numero: numeroRemetente,
      nomeContato,
      textoResposta: '❌ Só administradores podem alterar cargos de usuários.'
    });
  }

  const niveisValidos = ['Admin', 'Operador', 'Consultor'];
  if (!niveisValidos.includes(nivelNovo)) {
    return output({
      tipo: 'gerenciar_usuario',
      autorizado: false,
      numero: numeroRemetente,
      nomeContato,
      textoResposta: `❌ Cargo inválido. Use: ${niveisValidos.join(' ou ')}.`
    });
  }

  const usuarioAlvoExistente = usuarios.find(u => String(u.Numero) === numeroAlvo);
  let nomeAlvo;
  if (nomeInformado) {
    nomeAlvo = nomeInformado;
  } else if (numeroAlvo === numeroRemetenteLimpo) {
    nomeAlvo = nomeContato;
  } else {
    nomeAlvo = usuarioAlvoExistente ? usuarioAlvoExistente.Nome : '';
  }

  return output({
    tipo: 'gerenciar_usuario',
    autorizado: true,
    numero: numeroRemetente,
    nomeContato,
    NumeroAlvo: numeroAlvo,
    NivelNovo: nivelNovo,
    NomeAlvo: nomeAlvo,
    textoResposta: nomeAlvo
      ? `✅ Cargo atualizado: numero ${numeroAlvo} (${nomeAlvo}) agora é ${nivelNovo}.`
      : `✅ Cargo atualizado: numero ${numeroAlvo} agora é ${nivelNovo}.`
  });
}
// Bloqueia comandos de registro para quem só tem acesso de consulta.
function bloqueadoConsultor() {
  if (nivelAtual === 'Consultor') {
    return output({
      tipo: 'erro_coleta',
      numero: numeroRemetente,
      nomeContato,
      textoResposta: '❌ Consultores têm acesso somente de consulta. Peça a um administrador para registrar isso.'
    });
  }
  return null;
}
// --- COLETA TANQUE TERRA ---
if (/registrar\s+coleta\s+tanques?\s+terra/i.test(texto)) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  const matchTanques = texto.match(/tanques?\s+terra\s+([a-z0-9,\s]+?)\s+data\s+(\d{2}\/\d{2}\/\d{4})/i);

  if (!matchTanques) {
    return output({
      tipo: 'erro_coleta',
      numero: numeroRemetente,
      nomeContato,
      textoResposta:
        '❌ Não foi possível registrar a coleta de terra.\n\n' +
        'Formato esperado:\n"registrar coleta tanque(s) terra <número(s)> data <dd/mm/aaaa>"'
    });
  }

  const tanques = matchTanques[1].split(',').map(t => t.trim()).filter(Boolean);
  const dataColeta = matchTanques[2];

  if (tanques.length === 0) {
    return output({
      tipo: 'erro_coleta',
      numero: numeroRemetente,
      nomeContato,
      textoResposta:
        '❌ Não foi possível registrar a coleta de terra — nenhum tanque reconhecido.\n\n' +
        'Formato esperado:\n"registrar coleta tanque(s) terra <número(s)> data <dd/mm/aaaa>"'
    });
  }

  if (tanques.length > 8) {
    return output({
      tipo: 'erro_coleta',
      numero: numeroRemetente,
      nomeContato,
      textoResposta:
        `❌ Só é possível registrar até 8 tanques por mensagem (você enviou ${tanques.length}). ` +
        'Divida em mais de uma mensagem.'
    });
  }

  const itensColeta = [];
  let drops = [];
  let bagsArquivo = [];

  tanques.forEach((tanque, idx) => {
    const idColeta = `CT-${Date.now()}-${idx}`;

    itensColeta.push({ idColeta, tanque, dataColeta, responsavel: nomeContato });
    drops = drops.concat(calcularDrops(dataColeta, idColeta, tanque, 'Terra', null));
    bagsArquivo.push(calcularArquivo(dataColeta, idColeta, tanque, null));
  });

  return output({
    tipo: 'coleta_terra',
    dataColeta,
    tanques,
    itensColeta,
    drops,
    bagsArquivo,
    numero: numeroRemetente,
    nomeContato,
    textoResposta:
      `✅ Registro de tanque terra efetuado com sucesso por ${nomeContato}.\n\nTanques: ${tanques.join(', ')}\n` +
      `Data: ${dataColeta}\n` +
      `Total: ${tanques.length} tanque${tanques.length === 1 ? '' : 's'}`
  });
}

// --- COLETA TANQUE NAVIO ---
if (/coleta navio/i.test(texto)) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  const matchNavio = texto.match(/coleta\s+navio\s+(.+?)\s+tanques\s+([a-z0-9,\s]+?)\s+data\s+(\d{2}\/\d{2}\/\d{4})/i);

  if (!matchNavio) {
    return output({
      tipo: 'erro_coleta',
      numero: numeroRemetente,
      nomeContato,
      textoResposta:
        '❌ Não foi possível registrar a coleta de navio.\n\n' +
        'Formato esperado:\n"Coleta navio <nome> tanques <lista separada por vírgula> data <dd/mm/aaaa>"'
    });
  }

  const navio = matchNavio[1].trim();
  const tanques = matchNavio[2].split(',').map(t => t.trim().toUpperCase()).filter(Boolean);
  const dataColeta = matchNavio[3];

  if (!navio || tanques.length === 0) {
    return output({
      tipo: 'erro_coleta',
      numero: numeroRemetente,
      nomeContato,
      textoResposta:
        '❌ Não foi possível registrar a coleta de navio — nome do navio ou lista de tanques veio vazia.\n\n' +
        'Formato esperado:\n"Coleta navio <nome> tanques <lista separada por vírgula> data <dd/mm/aaaa>"'
    });
  }

  const itensColeta = [];
  let drops = [];
  let arquivosNavio = [];

  tanques.forEach((tanque, idx) => {
    const idColeta = `CN-${Date.now()}-${idx}`;

    itensColeta.push({
      idColeta,
      navio,
      tanque,
      dataColeta,
      responsavel: nomeContato
    });

    drops = drops.concat(
      calcularDrops(dataColeta, idColeta, tanque, 'Navio', navio)
    );

    arquivosNavio.push(
      calcularArquivo(dataColeta, idColeta, tanque, navio)
    );
  });

  return output({
    tipo: 'coleta_navio',
    navio,
    dataColeta,
    tanques,
    itensColeta,
    drops,
    arquivosNavio,
    numero: numeroRemetente,
    nomeContato,
    textoResposta:
      `✅ Registro de tanque navio efetuado com sucesso por ${nomeContato}.\n\nNavio: ${navio}\n` +
      `Tanques: ${tanques.join(', ')}\n` +
      `Data: ${dataColeta}\n` +
      `Total: ${tanques.length} tanque${tanques.length === 1 ? '' : 's'}`
  });
}

// --- NFC PLACA A PLACA (C.T, B.L e WORT dos tanques) e REPETIÇÃO (reanálise) ---
// Análise do comando: ct (C.T 48h), bl72, bl120 (bl sozinho = bl120), wort profundidade|superficie 120h|240h
function analiseNfc(txt) {
  let m = txt.match(/\bwort\s+(profundidade|superficie)\s+(120|240)\s*h?\b/);
  if (m) return { sub: 'WORT', metodo: m[1] === 'superficie' ? 'Superficie' : 'Profundidade', etapa: m[2] === '120' ? 'pre' : 'final',
    rotulo: `WORT ${m[1] === 'superficie' ? 'Superfície' : 'Profundidade'} ${m[2]}h` };
  if (/\bbl\s*72\s*h?\b/.test(txt)) return { sub: 'BL', metodo: 'Profundidade', etapa: 'pre', rotulo: 'B.L 72h' };
  if (/\bbl(\s*120\s*h?)?\b/.test(txt)) return { sub: 'BL', metodo: 'Profundidade', etapa: 'final', rotulo: 'B.L 120h' };
  if (/\bc\.?t(\s*48\s*h?)?\b/.test(txt)) return { sub: 'CT', metodo: 'Profundidade', etapa: 'final', rotulo: 'C.T 48h' };
  return null;
}
const FRASCO = { normal: 'Normal', stress: 'Stress' };

// Repetição (ou reanálise): só para tanque com desvio aberto. Nunca vira análise nova (vem antes do
// registro de análise). Ex.: "repetição do tanque 47 stress bl120" / "reanálise do tanque 47"
if (/^(?:repeticao|reanalise|re-analise)\b/.test(ajudaBusca)) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  const mT = ajudaBusca.match(/\btanques?\s+([a-z0-9]+)/);
  if (!mT) {
    return output({ tipo: 'erro_coleta', numero: numeroRemetente, nomeContato,
      textoResposta: '❌ Diga o tanque da repetição. Ex.: repetição do tanque 47 stress bl120' });
  }
  const an = analiseNfc(ajudaBusca.replace(/\btanques?\s+[a-z0-9]+/, ' '));
  const mN = ajudaBusca.match(/\bnavio\s+(.+?)(?=\s+(?:normal|stress|ct|c\.t|bl\d*|wort|data|coleta)\b|\s*,|$)/);
  const mF = ajudaBusca.match(/\b(normal|stress)\b/);
  return output({ tipo: 'repeticao_nfc', tanque: mT[1].toUpperCase(), navio: mN ? mN[1].trim().toUpperCase() : '',
    frasco: mF ? FRASCO[mF[1]] : '', sub: an ? an.sub : '', metodo: an ? an.metodo : '', etapa: an ? an.etapa : '',
    rotulo: an ? an.rotulo : '', numero: numeroRemetente, nomeContato });
}

// Placas (triplicata): "ct do tanque 47 normal 12,8,15" / "bl72 do tanque 5 navio d.sky 123 stress 0,1,0 coleta 01/10/2026"
// 0 e <1 = "<1"; ">300" = incontável. Sempre as 3 placas, na ordem da bancada.
const matchPlacas = ajudaBusca.match(/^(c\.?t(?:\s*48)?|bl\s*72|bl\s*120|bl|wort\s+(?:profundidade|superficie)\s+(?:120|240))\s*h?\s+(?:d[oa]s?\s+)?tanques?\s+([a-z0-9]+)(?:\s+(?:do\s+)?navio\s+(.+?))?\s*,?\s+(normal|stress)\s*:?\s*([<>]?\s*\d+(?:\s*(?:,|\be\b)\s*[<>]?\s*\d+)*)(?:\s*,?\s*(?:data|coleta)(?:\s+da\s+coleta)?\s+(\d{2}\/\d{2}\/\d{4}))?$/);
if (matchPlacas) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  const an = analiseNfc(matchPlacas[1]);
  const erroPlacas = t => output({ tipo: 'erro_coleta', numero: numeroRemetente, nomeContato, textoResposta: t });
  const valores = matchPlacas[5].split(/\s*(?:,|\be\b)\s*/).filter(Boolean);
  if (valores.length !== 3) {
    return erroPlacas(`❌ Mande as 3 placas (triplicata), na ordem da bancada. Ex.: ${matchPlacas[1]} do tanque ${matchPlacas[2].toUpperCase()} ${matchPlacas[4]} 12,8,15 (0 ou <1 = sem colônia)`);
  }
  const placas = [];
  for (const [i, v] of valores.entries()) {
    const m = v.replace(/\s+/g, '').match(/^([<>]?)(\d+)$/);
    const valor = Number(m[2]);
    if (m[1] === '<' && valor !== 1) return erroPlacas('❌ Placa sem colônia é *0* ou *<1*. Outros valores com "<" não valem.');
    placas.push(m[1] === '>' ? { placa: i + 1, sinal: '>', valor }
      : (valor === 0 || m[1] === '<') ? { placa: i + 1, sinal: '<', valor: 1 } : { placa: i + 1, sinal: '=', valor });
  }
  return output({ tipo: 'placas_nfc', ...an, tanque: matchPlacas[2].toUpperCase(), navio: (matchPlacas[3] || '').trim().toUpperCase(),
    frasco: FRASCO[matchPlacas[4]], placas, dataColeta: matchPlacas[6] || '', numero: numeroRemetente, nomeContato });
}
// Começou como placa de tanque mas fugiu do formato: explica em vez de mandar para a IA
if (/^(c\.?t|bl\s*\d*|wort)\b[^]*\btanques?\s+[a-z0-9]+[^]*\b(normal|stress)\b[^]*\d/.test(ajudaBusca)) {
  return output({ tipo: 'erro_coleta', numero: numeroRemetente, nomeContato,
    textoResposta: '❌ Formato das placas: <ct|bl72|bl120|wort profundidade 120h|...> do tanque <t> [navio <navio>] <normal|stress> <placa 1>,<placa 2>,<placa 3>\nEx.: ct do tanque 47 normal 12,8,15' });
}
// --- ANALISE DE TANQUE (NORMAL / STRESS) — terra e navio, lista de tanques ---
// (?<!...): "reanálise" nunca vira análise nova (é repetição; spec NFC, decisão 11)
const regexAnaliseTanque = /(?<![a-zà-ü])an[aá]lise\s+(?:dos?\s+)?(normal|stress)\s+(?:dos?\s+)?tanques?\s+(?:terra\s+)?([a-z0-9,\s]+?)(?:\s+navio\s+(.+?))?\s*,?\s*data\s+(\d{2}\/\d{2}\/\d{4})/i;
const matchAnaliseTanque = texto.match(regexAnaliseTanque);

if (matchAnaliseTanque) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  const tipoFrascoBruto = matchAnaliseTanque[1].toLowerCase();
  const tipoFrasco = tipoFrascoBruto === 'stress' ? 'Stress' : 'Normal';
  const tanques = matchAnaliseTanque[2].split(',').map(t => t.trim().toUpperCase()).filter(Boolean);
  const navio = matchAnaliseTanque[3] ? matchAnaliseTanque[3].trim().toUpperCase() : null;
  const tipoTanque = navio ? 'Navio' : 'Terra';
  const dataAnalise = matchAnaliseTanque[4];

  if (tanques.length === 0) {
    return output({
      tipo: 'erro_coleta',
      numero: numeroRemetente,
      nomeContato,
      textoResposta:
        '❌ Não foi possível registrar a análise — nenhum tanque reconhecido.\n\n' +
        'Formato esperado:\n"Analise do normal/stress do tanque(s) <número(s)>[ navio <nome>], data <dd/mm/aaaa>"'
    });
  }

  const limite = navio ? 16 : 8;
  if (tanques.length > limite) {
    return output({
      tipo: 'erro_coleta',
      numero: numeroRemetente,
      nomeContato,
      textoResposta:
        `❌ Só é possível registrar até ${limite} tanques por mensagem${navio ? ' de navio' : ''} (você enviou ${tanques.length}). ` +
        'Divida em mais de uma mensagem.'
    });
  }

  const idColetaBase = `AN-${Date.now()}`;
  let analises = [];
  tanques.forEach((tanque, idx) => {
    const idColeta = `${idColetaBase}-${idx}`;
    analises = analises.concat(calcularAnalises(dataAnalise, idColeta, tanque, tipoFrasco, tipoTanque, navio));
  });
  const analiseCT = analises.find(a => a.subAnalise === 'CT');
  const analiseBL = analises.find(a => a.subAnalise === 'BL');
  const analiseWORT = analises.find(a => a.subAnalise === 'WORT');

  return output({
    tipo: 'registro_analise',
    tipoFrasco,
    tanques,
    tipoTanque,
    navio,
    dataAnalise,
    analises,
    numero: numeroRemetente,
    nomeContato,
    textoResposta:
      `✅ Análise ${tipoFrasco} registrada.\n\n` +
      `Tanques: ${tanques.join(', ')}${navio ? ` (Navio ${navio})` : ''}\n` +
      `Data: ${dataAnalise}\n` +
      `Data final CT: ${analiseCT.dataLeituraFinal}\n` +
      `Data pré-leitura BL: ${analiseBL.dataPreLeitura}\n` +
      `Data final BL: ${analiseBL.dataLeituraFinal}\n` +
      `Data pré-leitura WORT: ${analiseWORT.dataPreLeitura}\n` +
      `Data final WORT: ${analiseWORT.dataLeituraFinal}\n` +
      `Total: ${tanques.length} tanque${tanques.length === 1 ? '' : 's'}\n` +
      `Analises realizadas: CT, BL, WORT (Profundidade e Superfície)`
  });
}

// --- CONSULTA DE DROPS ---
if (/^drops?\s*(previstos)?\s*(para)?\s*hoje\??$/i.test(texto.trim())) {
