// --- RELATÓRIO DO DIA (NFC: tanques terra e navio) ---
// --- RELATÓRIO DO DIA: todos os blocos (FCOJ recebimento e embarque; NFC tank farm e navio) ---
//   "relatório do dia"                       -> os quatro blocos, acompanhando o andamento (✅ = lido)
//   "relatório do dia completo"              -> só o que já foi lido, com a Situação (ok / não ok)
//   "relatório do dia recebimento|embarque"  -> só aquele bloco do concentrado
//   "relatório do dia concentrado"           -> recebimento e embarque
//   "relatório do dia tanques [terra|navio]" -> só NFC
const matchRelatorioDia = ajudaBusca
  .replace(/^relatorio\s+completo\b/, 'relatorio do dia completo')
  .match(/^relatorio\s+(?:do\s+dia|de\s+hoje)(?:\s+(completo))?(?:\s+(?:dos?\s+)?(tanques?(?:\s+(?:de\s+)?(?:terra|navio))?|recebimento|embarque|concentrado|fcoj))?(?:\s+(completo))?$/);
if (matchRelatorioDia) {
  const quero = matchRelatorioDia[2] || '';
  const completo = !!(matchRelatorioDia[1] || matchRelatorioDia[3]);
  let blocosNfc = ['Tank farm', 'Navio'];
  let blocosConc = ['Recebimento', 'Embarque'];
  if (/^tanques?/.test(quero)) {
    blocosConc = [];
    if (/terra/.test(quero)) blocosNfc = ['Tank farm'];
    else if (/navio/.test(quero)) blocosNfc = ['Navio'];
  } else if (quero === 'recebimento') {
    blocosNfc = []; blocosConc = ['Recebimento'];
  } else if (quero === 'embarque') {
    blocosNfc = []; blocosConc = ['Embarque'];
  } else if (quero === 'concentrado' || quero === 'fcoj') {
    blocosNfc = [];
  }
  return output({ tipo: 'relatorio_dia', blocosNfc, blocosConc, completo, numero: numeroRemetente, nomeContato });
}
const matchRelatorio = ajudaBusca.match(/^relatorio\s+(?:do\s+dia|de\s+hoje)(?:\s+(?:dos\s+)?tanques?(?:\s+(terra|navio))?)?$/);

if (matchRelatorio) {
  const qual = matchRelatorio[1];
  return output({
    tipo: 'relatorio_nfc',
    blocoFiltro: qual === 'terra' ? 'Tank farm' : (qual === 'navio' ? 'Navio' : ''),
    numero: numeroRemetente,
    nomeContato
  });
}
// --- CONCENTRADO: lista de lotes "1-5,7,9-10" -> [1,2,3,4,5,7,9,10] ---
function expandirLotes(texto) {
  const lotes = [];
  for (const parte of String(texto).split(',').map(p => p.trim()).filter(Boolean)) {
    const faixa = parte.match(/^(\d+)\s*-\s*(\d+)$/);
    if (faixa) {
      const ini = Number(faixa[1]), fim = Number(faixa[2]);
      if (ini < 1 || fim < ini || fim - ini > 200) return null;
      for (let n = ini; n <= fim; n++) lotes.push(n);
    } else if (/^\d+$/.test(parte) && Number(parte) > 0) {
      lotes.push(Number(parte));
    } else {
      return null;
    }
  }
  return lotes.length ? lotes : null;
}

// --- RECEBIMENTO DE LOTES (concentrado) ---
const matchRecebimento = texto.trim().match(/^recebimento\s+(?:do\s+)?load\s+(\w+)\s*,?\s*item\s+(\w+)\s*,?\s*f[aá]brica\s+([\w.\-]+)\s*,?\s*lotes?\s+([\d,\s\-]+?)(?:\s*,?\s*data\s+(\d{2}\/\d{2}\/\d{4}))?\s*$/i);

if (matchRecebimento) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  const lotes = expandirLotes(matchRecebimento[4]);
  if (!lotes) {
    return output({
      tipo: 'erro_coleta', numero: numeroRemetente, nomeContato,
      textoResposta: '❌ Não entendi os lotes. Use faixas e vírgulas, ex.: lotes 1-14 ou lotes 1-5,7,9-10'
    });
  }
  return output({
    tipo: 'recebimento',
    load: matchRecebimento[1],
    item: matchRecebimento[2],
    fabrica: matchRecebimento[3].toUpperCase(),
    lotes: [...new Set(lotes)].sort((a, b) => a - b),
    dataRecebimento: matchRecebimento[5] || new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' }),
    numero: numeroRemetente,
    nomeContato
  });
}

// --- CRIAR COMPOSTAS: "compostas do load 77001 (1-5)(6-10)(11,12,15)" ---
const matchCompostas = texto.trim().match(/^compostas?\s+(?:do\s+)?load\s+(\w+)(?:\s*,?\s*item\s+(\w+))?\s*,?\s*((?:\(\s*[^()]*\)\s*)+)$/i);

if (matchCompostas) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  const grupos = [...matchCompostas[3].matchAll(/\(([^()]*)\)/g)].map(m => m[1]);
  const compostas = [];
  for (let i = 0; i < grupos.length; i++) {
    const lotes = expandirLotes(grupos[i]);
    if (!lotes) {
      return output({
        tipo: 'erro_coleta', numero: numeroRemetente, nomeContato,
        textoResposta: `❌ Não entendi a composta ${i + 1}: "(${grupos[i]})". Nada foi gravado.\n\nFormato: compostas do load 77001 (1-5)(6-10)(11,12,15)`
      });
    }
    compostas.push([...new Set(lotes)].sort((a, b) => a - b));
  }
  const todos = compostas.flat();
  const repetidos = [...new Set(todos.filter((l, i) => todos.indexOf(l) !== i))];
  if (repetidos.length) {
    return output({
      tipo: 'erro_coleta', numero: numeroRemetente, nomeContato,
      textoResposta: `❌ Lote(s) ${repetidos.join(', ')} em mais de uma composta. Nada foi gravado.`
    });
  }
  return output({
    tipo: 'criar_compostas',
    load: matchCompostas[1],
    item: matchCompostas[2] || '',
    compostas,
    numero: numeroRemetente,
    nomeContato
  });
}
// --- EMBARQUE: "A1-A5" -> "1-5" (as amostras também podem ser escritas só com números) ---
function limparAmostras(s) { return String(s).replace(/\bA(?=\d)/gi, ''); }

// --- EMBARQUE (concentrado): "embarque navio O.SKY 133 linha 2 fase 2 load 77010 item 444 amostras 1-10 [data dd/mm/aaaa]" ---
const matchEmbarque = limparAmostras(texto.trim()).match(/^embarque\s+(?:do\s+)?navio\s+(.+?)\s*,?\s*linha\s+(\d+)\s*,?\s*fase\s+(\d+)\s*,?\s*load\s+(\w+)\s*,?\s*item\s+(\w+)\s*,?\s*amostras?\s+([\d,\s\-]+?)(?:\s*,?\s*data\s+(\d{2}\/\d{2}\/\d{4}))?\s*$/i);

if (matchEmbarque) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  const navio = matchEmbarque[1].replace(/\s+/g, ' ').trim().toUpperCase();
  if (!/\s\d+$/.test(navio)) {
    return output({
      tipo: 'erro_coleta', numero: numeroRemetente, nomeContato,
      textoResposta: '❌ Informe o navio com a viagem. Ex.: embarque navio O.SKY 133 linha 2 fase 2 load 77010 item 444 amostras 1-10'
    });
  }
  const amostras = expandirLotes(matchEmbarque[6]);
  if (!amostras) {
    return output({
      tipo: 'erro_coleta', numero: numeroRemetente, nomeContato,
      textoResposta: '❌ Não entendi as amostras. Use faixas e vírgulas, ex.: amostras 1-10 ou amostras A1-A5,A7'
    });
  }
  return output({
    tipo: 'embarque',
    navio,
    linha: matchEmbarque[2],
    fase: matchEmbarque[3],
    load: matchEmbarque[4],
    item: matchEmbarque[5],
    amostras: [...new Set(amostras)].sort((a, b) => a - b),
    dataEmbarque: matchEmbarque[7] || new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' }),
    numero: numeroRemetente,
    nomeContato
  });
}

// --- CRIAR COMPOSTAS DE EMBARQUE: "compostas do navio O.SKY 133 linha 2 fase 2 (A1-A5)(A6-A10)" ---
const matchCompostasEmb = limparAmostras(texto.trim()).match(/^compostas?\s+(?:do\s+)?navio\s+(.+?)\s*,?\s*linha\s+(\d+)\s*,?\s*fase\s+(\d+)\s*,?\s*((?:\(\s*[^()]*\)\s*)+)$/i);

if (matchCompostasEmb) {
