  const navio = matchCompostasEmb[1].replace(/\s+/g, ' ').trim().toUpperCase();
  const grupos = [...matchCompostasEmb[4].matchAll(/\(([^()]*)\)/g)].map(m => m[1]);
  const compostas = [];
  for (let i = 0; i < grupos.length; i++) {
