      });
    }
    compostas.push([...new Set(amostras)].sort((a, b) => a - b));
  }
  const todas = compostas.flat();
  const repetidas = [...new Set(todas.filter((a, i) => todas.indexOf(a) !== i))];
  if (repetidas.length) {
    return output({
      tipo: 'erro_coleta', numero: numeroRemetente, nomeContato,
      textoResposta: `❌ Amostra(s) ${repetidas.map(a => 'A' + a).join(', ')} em mais de uma composta. Nada foi gravado.`
    });
