// --- HOWARD (embarque): consultas ---
//   "temos analise de howard para hoje?"  -> compostas de embarque sem Howard
//   "quais howards foram lidos hoje?"     -> Howards gravados hoje
const howardEtapa =
  ajudaBusca.match(/^(?:temos|tem|quais|qual)?\s*(?:analises?\s+(?:de\s+)?)?howards?\s+(?:para|pra|de)\s+hoje$/) ? 'pendentes' :
  (ajudaBusca.match(/^(?:quais|qual)\s+howards?\s+(?:foram|ja\s+foram)\s+lidos?\s+hoje$/) ? 'lidos' : null);
if (howardEtapa) {
  return output({ tipo: 'consulta_howard', etapa: howardEtapa, numero: numeroRemetente, nomeContato });
}

// --- HOWARD (embarque): registrar a porcentagem ---
//   "howard #20 2%"
//   "Analise da composta de Howard do navio O.SKY 133 linha 2 fase 2 amostras 1-5, foi 2%"
if (/\bhowards?\b/.test(ajudaBusca) && /\d\s*%\s*$/.test(ajudaBusca)) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  const erroHoward = t => output({ tipo: 'erro_coleta', numero: numeroRemetente, nomeContato, textoResposta: t });
  const pct = ajudaBusca.match(/(\d+(?:[.,]\d+)?)\s*%\s*$/);
  const perc = Number(pct[1].replace(',', '.'));
  // Howard é lido em 50 campos e cada campo positivo vale 2%: a porcentagem é sempre par
  if (!(perc >= 0 && perc <= 100) || perc % 2 !== 0) {
    return erroHoward(`❌ O Howard é lido em 50 campos, então a porcentagem é sempre par (0%, 2%, 4%...). Recebi ${pct[1]}%. Nada foi gravado.`);
  }
  const mIdHoward = ajudaBusca.match(/#\s*(\d+)/);
  if (mIdHoward) {
    return output({ tipo: 'howard_registrar', compostaId: Number(mIdHoward[1]), percentual: perc,
      refNavio: '', refLinha: '', refFase: '', refGrupos: [], numero: numeroRemetente, nomeContato });
  }
  const textoSemPct = texto.trim().replace(/[,\s]*(?:foi|deu|=)?\s*\d+(?:[.,]\d+)?\s*%\s*$/i, '');
  const refH = extrairRef(textoSemPct);
  if (refH.navio && refH.grupos.length === 1 && refH.grupos[0]) {
    return output({ tipo: 'howard_registrar', compostaId: '', percentual: perc,
      refNavio: refH.navio, refLinha: refH.linha, refFase: refH.fase, refGrupos: refH.grupos,
      numero: numeroRemetente, nomeContato });
  }
  return erroHoward('❌ Não entendi o Howard. Exemplos:\nhoward #20 2%\nAnalise da composta de Howard do navio O.SKY 133 linha 2 fase 2 amostras 1-5, foi 2%');
}

// --- TAB DE NFC (tank farm, por tanque; o comando sempre cita a data da coleta) ---
//   "Tab feito dos tanques terra 42,43 coleta 28/09/2026 [data dd/mm/aaaa]"
const matchTabNfc = texto.trim().match(/^tabs?\s+feitos?\s+(?:d[aeo]s?\s+)?tanques?\s+(?:terra\s+)?([\d,\s]+?)\s*,?\s*coleta\s+(\d{2}\/\d{2}\/\d{4})(?:\s*,?\s*data\s+(\d{2}\/\d{2}\/\d{4}))?\s*$/i);
if (matchTabNfc) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  const tanquesNfc = [...new Set(matchTabNfc[1].split(/[,\s]+/).filter(Boolean))];
  if (!tanquesNfc.length || tanquesNfc.some(t => !/^\d+$/.test(t))) {
    return output({ tipo: 'erro_coleta', numero: numeroRemetente, nomeContato,
      textoResposta: '❌ Não entendi os tanques. Ex.: Tab feito dos tanques terra 42,43 coleta 28/09/2026' });
  }
  if (tanquesNfc.length > 8) {
    return output({ tipo: 'erro_coleta', numero: numeroRemetente, nomeContato,
      textoResposta: '❌ Máximo de 8 tanques por mensagem. Nada foi gravado.' });
  }
  return output({ tipo: 'tab_feito_nfc', tanques: tanquesNfc, dataColeta: matchTabNfc[2],
    dataFeito: matchTabNfc[3] || new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' }),
    numero: numeroRemetente, nomeContato });
}

// TAB de NFC em confirmação: "tab tanque terra 42 coleta 28/09/2026 em confirmação"
