// --- C.T e B.L (72h e 120h) por lote (recebimento) e por amostra (embarque) ---
function nomeAnaliseCt(s) {
  const t = String(s).toLowerCase().replace(/\s+/g, '');
  return t === 'ct' ? 'CT' : (t === 'bl72' ? 'BL72' : 'BL120');
}

// consultas: "quais ct tenho para ler hoje?" / "quais bl72 foram lidos hoje?"
const matchCtConsulta =
  ajudaBusca.match(/^(?:quais|qual|temos|tem)?\s*(ct|bl\s*72|bl\s*120|bl)s?\s+(?:(?:tenho|temos|tem)\s+)?(?:para|pra)\s+ler(?:\s+hoje)?$/) ||
  ajudaBusca.match(/^(?:quais|qual)\s+(ct|bl\s*72|bl\s*120|bl)s?\s+(?:foram|ja\s+foram)\s+lidos?\s+hoje$/);
if (matchCtConsulta) {
  return output({ tipo: 'consulta_contagens', analise: nomeAnaliseCt(matchCtConsulta[1]),
    etapa: /\bforam\b/.test(ajudaBusca) ? 'lidos' : 'ler', numero: numeroRemetente, nomeContato });
}

// registro, com vários grupos na mesma mensagem:
//   "ct load 77001 lote 4 deu 10, lotes 5-10 deu <10"
//   "bl72 load 77001 item 444 lotes 1-14 deu <10"
//   "ct navio O.SKY 133 linha 2 fase 2 amostras 1-5 deu <10, amostra 6 deu 30"
const matchCtReg = limparAmostras(texto.trim()).match(/^(ct|bl\s*72|bl\s*120|bl)\s+(?:load\s+(\w+)(?:\s*,?\s*item\s+(\w+))?|navio\s+(.+?)\s*,?\s*linha\s+(\d+)\s*,?\s*fase\s+(\d+))\s*,?\s*((?:lotes?|amostras?)\s+.+)$/i);
if (matchCtReg) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  const erroCt = t => output({ tipo: 'erro_coleta', numero: numeroRemetente, nomeContato, textoResposta: t });
  const exemplo = '\n\nExemplos:\nct load 77001 lote 4 deu 10, lotes 5-10 deu <10\nct navio O.SKY 133 linha 2 fase 2 amostras 1-5 deu <10, amostra 6 deu 30';
  const grupos = [];
  const vistos = new Set();
  for (const parte of matchCtReg[7].split(/(?:\s*,\s*|\s+)(?=(?:lotes?|amostras?)\s+\d)/i)) {
    const g = parte.trim().match(/^(?:lotes?|amostras?)\s+([\d,\s\-]+?)\s*(?:deu|foi|=)\s*([<>=]?)\s*(\d+(?:[.,]\d+)?)\s*$/i);
    if (!g) return erroCt(`❌ Não entendi "${parte.trim()}". Nada foi gravado.${exemplo}`);
    const numeros = expandirLotes(g[1].replace(/[\s,]+$/, ''));
    if (!numeros) return erroCt(`❌ Não entendi os números "${g[1].trim()}". Use faixas e vírgulas, ex.: lotes 5-10. Nada foi gravado.`);
    const unicos = [...new Set(numeros)].sort((a, b) => a - b);
    const repetidos = unicos.filter(n => vistos.has(n));
    if (repetidos.length) return erroCt(`❌ O número ${repetidos[0]} aparece em mais de um grupo. Nada foi gravado.`);
    unicos.forEach(n => vistos.add(n));
    grupos.push({ numeros: unicos, sinal: g[2] || '=', valor: Number(g[3].replace(',', '.')) });
  }
  const todosNumeros = [...vistos].sort((a, b) => a - b);
  if (todosNumeros.length > 200) return erroCt('❌ Máximo de 200 lotes/amostras por mensagem. Nada foi gravado.');
  const ehLoad = !!matchCtReg[2];
  return output({
    tipo: 'contagem_registrar',
    analise: nomeAnaliseCt(matchCtReg[1]),
    origem: ehLoad ? 'recebimento' : 'embarque',
    load: matchCtReg[2] || '',
    item: matchCtReg[3] || '',
    navio: ehLoad ? '' : matchCtReg[4].replace(/\s+/g, ' ').trim().toUpperCase(),
    linha: matchCtReg[5] || '',
    fase: matchCtReg[6] || '',
    grupos,
    numeros: todosNumeros,
    numero: numeroRemetente,
    nomeContato
  });
}

// --- TAB FEITO: "tab feito das compostas #4 a #6" ou "tab feito do load 77001" ---
const matchTabFeito = texto.trim().match(/^tabs?\s+feitos?\s+(?:d[aeo]s?\s+)?(?:compostas?\s+([#\d\s,ae\-]+?)|load\s+(\w+)(?:\s*,?\s*item\s+(\w+))?)(?:\s*,?\s*data\s+(\d{2}\/\d{2}\/\d{4}))?\s*$/i);

if (matchTabFeito) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  const ids = [];
  if (matchTabFeito[1]) {
    // "#4 a #6", "#4-#6", "#4, #5 e #7"
    for (const m of matchTabFeito[1].matchAll(/#?(\d+)(?:\s*(?:a|-)\s*#?(\d+))?/g)) {
      const ini = Number(m[1]), fim = m[2] ? Number(m[2]) : ini;
      if (fim < ini || fim - ini > 100) { ids.length = 0; break; }
      for (let n = ini; n <= fim; n++) ids.push(n);
    }
    if (!ids.length) {
      return output({ tipo: 'erro_coleta', numero: numeroRemetente, nomeContato,
        textoResposta: '❌ Não entendi as compostas. Ex.: tab feito das compostas #4 a #6' });
    }
  }
  return output({
    tipo: 'tab_feito',
    compostaIds: [...new Set(ids)],
    load: matchTabFeito[2] || '',
    item: matchTabFeito[3] || '',
    dataFeito: matchTabFeito[4] || new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' }),
    numero: numeroRemetente,
    nomeContato
  });
}

// --- CONSULTAS DO TAB: espalhar hoje, ler hoje, lidos hoje ---
const matchTabConsulta =
  ajudaBusca.match(/^(?:quais|qual|temos|tem)?\s*tabs?\s+(?:(?:tenho|temos|tem)\s+)?(?:para|pra)\s+(espalhar|ler)(?:\s+hoje)?$/) ||
  ajudaBusca.match(/^(?:quais|qual)\s+tabs?\s+(?:foram|ja\s+foram)\s+(lidos?)\s+hoje$/);

if (matchTabConsulta) {
