}
// --- TAB: etapa do dia feita ("tabs de hoje espalhados" / "tabs de hoje lidos") ---
const matchTabEtapa = ajudaBusca.match(/^tabs?\s+de\s+hoje\s+(espalhados?|lidos?)$/);
if (matchTabEtapa) {
