// --- Resultado da confirmação: "confirmação do tab #5 positivo" ---
const matchTabRes = ajudaBusca.match(/^confirmacao\s+(?:do\s+)?tabs?\s+(?:da\s+composta\s+)?#\s*(\d+)\s*,?\s*(?:deu\s+)?(positivo|negativo)$/);
if (matchTabRes) {
