    resultado: matchTabRes[2] === 'positivo' ? 'Positivo' : 'Negativo', numero: numeroRemetente, nomeContato });
}
// --- COLIFORMES (mesmos tipos do TAB, com teste: 'COLIFORMES') ---
const matchColiFeito = texto.trim().match(/^coliformes?\s+feitos?\s+(?:d[aeo]s?\s+)?(?:compostas?\s+([#\d\s,ae\-]+?)|load\s+(\w+)(?:\s*,?\s*item\s+(\w+))?)(?:\s*,?\s*data\s+(\d{2}\/\d{2}\/\d{4}))?\s*$/i);
if (matchColiFeito) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  const ids = [];
  if (matchColiFeito[1]) {
    for (const m of matchColiFeito[1].matchAll(/#?(\d+)(?:\s*(?:a|-)\s*#?(\d+))?/g)) {
      const ini = Number(m[1]), fim = m[2] ? Number(m[2]) : ini;
      if (fim < ini || fim - ini > 100) { ids.length = 0; break; }
      for (let n = ini; n <= fim; n++) ids.push(n);
    }
    if (!ids.length) {
      return output({ tipo: 'erro_coleta', numero: numeroRemetente, nomeContato,
        textoResposta: '❌ Não entendi as compostas. Ex.: coliformes feitos das compostas #4 a #6' });
    }
  }
  return output({ tipo: 'tab_feito', teste: 'COLIFORMES', compostaIds: [...new Set(ids)],
    load: matchColiFeito[2] || '', item: matchColiFeito[3] || '',
    dataFeito: matchColiFeito[4] || new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' }),
    numero: numeroRemetente, nomeContato });
}

const matchColiConsulta =
  ajudaBusca.match(/^(?:quais|qual|temos|tem)?\s*coliformes?\s+(?:(?:tenho|temos|tem)\s+)?(?:para|pra)\s+(estriar|ler)(?:\s+hoje)?$/) ||
  ajudaBusca.match(/^(?:quais|qual)\s+coliformes?\s+(?:foram|ja\s+foram)\s+(lidos?)\s+hoje$/);
if (matchColiConsulta) {
  const e = matchColiConsulta[1];
  return output({ tipo: 'consulta_tab', teste: 'COLIFORMES', etapa: e === 'estriar' ? 'espalhar' : (e.startsWith('lido') ? 'lidos' : 'ler'),
    numero: numeroRemetente, nomeContato });
}

const matchColiEtapa = ajudaBusca.match(/^coliformes?\s+de\s+hoje\s+(estriados?|lidos?)$/);
if (matchColiEtapa) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
