    numero: numeroRemetente, nomeContato });
}

// "coliformes #12 em confirmação" / "composta #12 coliformes em confirmação": abre a composta lote a lote
const matchColiAbrir = ajudaBusca.match(/^(?:coliformes?\s+(?:da\s+composta\s+)?#\s*(\d+)|composta\s+#\s*(\d+)\s*,?\s*coliformes?)\s+em\s+confirmacao$/);
if (matchColiAbrir) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  return output({ tipo: 'coli_abrir', teste: 'COLIFORMES', compostaId: Number(matchColiAbrir[1] || matchColiAbrir[2]),
    numero: numeroRemetente, nomeContato });
}

// resultado de um lote da composta aberta: "coliformes #12.3 positivo"
const matchColiRes = ajudaBusca.match(/^(?:confirmacao\s+(?:de\s+|dos?\s+)?)?coliformes?\s+(?:da\s+composta\s+)?#\s*(\d+)\.(\d+)\s*,?\s*(?:deu\s+)?(positivo|negativo)$/);
if (matchColiRes) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  return output({ tipo: 'tab_resultado', teste: 'COLIFORMES', compostaId: Number(matchColiRes[1]), lote: matchColiRes[2],
    resultado: matchColiRes[3] === 'positivo' ? 'Positivo' : 'Negativo', numero: numeroRemetente, nomeContato });
}
// --- FORMATO COMPLETO dos testes de composta (sem #): load, item e lotes por extenso ---
// Ex.: "Tab da composta load 77001, lotes 6-10, item 444, fabrica AQA, em confirmação"
function extrairRef(t0) {
  const t = limparAmostras(t0);
  const load = (t.match(/\bload\s+(\w+)/i) || [])[1] || '';
  const item = (t.match(/\bitem\s+(\w+)/i) || [])[1] || '';
  // embarque: "navio O.SKY 133 linha 2 fase 2"
  const emb = t.match(/\bnavio\s+(.+?)\s*,?\s*linha\s+(\d+)\s*,?\s*fase\s+(\d+)/i);
  const navio = emb ? emb[1].replace(/\s+/g, ' ').trim().toUpperCase() : '';
  const linha = emb ? emb[2] : '';
  const fase = emb ? emb[3] : '';
  const grupos = [...t.matchAll(/\(([^()]*)\)/g)].map(m => expandirLotes(m[1]));
  if (!grupos.length) {
    const m = t.match(/\b(?:lotes?|amostras?)\s+(\d[\d,;\s\-]*)/i);
    if (m) grupos.push(expandirLotes(m[1].replace(/[\s,]+$/, '')));
  }
  return { load, item, navio, linha, fase, grupos };
}
const textoRef = texto.trim();
const ehTab = /\btabs?\b/.test(ajudaBusca);
const ehColi = /\bcoliformes?\b/.test(ajudaBusca);
const ref = (/\bload\s+\w+/i.test(textoRef) || /\bnavio\s+.+?\blinha\s+\d+/i.test(textoRef)) ? extrairRef(textoRef) : null;
const refInvalida = ref && ref.grupos.some(g => !g);
const erroRef = () => output({ tipo: 'erro_coleta', numero: numeroRemetente, nomeContato,
  textoResposta: '❌ Não entendi os lotes da composta. Ex.: load 77001, lotes 1-5  ou  load 77001 (1-5)(6-10)  ou  navio O.SKY 133 linha 2 fase 2 (A1-A5)' });

if (ref && (ehTab || ehColi) && /^(?:tabs?|coliformes?)\s+feitos?\b/.test(ajudaBusca)) {
  // "tab feito do load 77001, item 444, fabrica AQA, lotes 1-5" / "coliformes feitos do load 77001 (1-5)(6-10)"
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  if (refInvalida) return erroRef();
  return output({ tipo: 'tab_feito', teste: ehTab ? 'TAB' : 'COLIFORMES', compostaIds: [],
    load: ref.load, item: ref.item, refGrupos: ref.grupos, navio: ref.navio, linha: ref.linha, fase: ref.fase, refNavio: ref.navio, refLinha: ref.linha, refFase: ref.fase,
    dataFeito: (textoRef.match(/data\s+(\d{2}\/\d{2}\/\d{4})/i) || [])[1] || new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' }),
    numero: numeroRemetente, nomeContato });
}

if (ref && /\bem\s+confirmacao$/.test(ajudaBusca) && (ehTab || ehColi)) {
  // TAB: direto; Coliformes: abre a composta (pergunta antes)
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  if (refInvalida || ref.grupos.length !== 1) return erroRef();
  return output({ tipo: ehTab ? 'tab_em_confirmacao' : 'coli_abrir', teste: ehTab ? 'TAB' : 'COLIFORMES',
    compostaId: '', refLoad: ref.load, refItem: ref.item, refGrupos: ref.grupos, refNavio: ref.navio, refLinha: ref.linha, refFase: ref.fase, numero: numeroRemetente, nomeContato });
}

const matchResFinal = ajudaBusca.match(/\b(positivo|negativo)$/);
if (ref && matchResFinal && (ehTab || /\bcomposta\b/.test(ajudaBusca) || ehColi)) {
  // TAB: "Confirmação do tab da composta load 77001, lotes 6-10, ..., positivo"
  // Coliformes (lote da composta aberta): "composta load 77001, lote 7 item 444, ..., da confirmação deu positivo"
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  if (refInvalida || ref.grupos.length !== 1) return erroRef();
  const resultado = matchResFinal[1] === 'positivo' ? 'Positivo' : 'Negativo';
  if (ehTab) {
    return output({ tipo: 'tab_resultado', teste: 'TAB', compostaId: '', refLoad: ref.load, refItem: ref.item,
      refGrupos: ref.grupos, refNavio: ref.navio, refLinha: ref.linha, refFase: ref.fase, resultado, numero: numeroRemetente, nomeContato });
  }
  if (ref.grupos[0].length !== 1) {
    return output({ tipo: 'erro_coleta', numero: numeroRemetente, nomeContato,
      textoResposta: '❌ Na confirmação de Coliformes o resultado é por lote. Ex.: composta load 77001, lote 7, da confirmação deu positivo' });
  }
  return output({ tipo: 'tab_resultado', teste: 'COLIFORMES', compostaId: '', lote: String(ref.grupos[0][0]),
    refLoad: ref.load, refItem: ref.item, refGrupos: [], refNavio: ref.navio, refLinha: ref.linha, refFase: ref.fase, resultado, numero: numeroRemetente, nomeContato });
}
// --- LEITURA DO DIA FINALIZADA: marca como lido tudo o que sai hoje (pergunta antes) ---
if (/^(?:leituras?\s+(?:do\s+dia\s+|de\s+hoje\s+)?finalizadas?|finalizar\s+(?:a\s+)?leituras?(?:\s+do\s+dia|\s+de\s+hoje)?)$/.test(ajudaBusca)) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  return output({ tipo: 'finalizar_dia', numero: numeroRemetente, nomeContato });
}

// --- DESVIO DE DROP ---
// Abrir (pergunta antes): "drop d5 do tanque 45 data 30/09/2026 não ok" (data = da coleta)
const matchDesvioAbrir = ajudaBusca.match(/^drops?\s+d\s*(5|10|15)\s+(?:do\s+)?tanques?\s+([a-z0-9]+)(?:\s+(?:do\s+)?navio\s+(.+?))?\s*,?\s*(?:data|coleta)(?:\s+da\s+coleta)?\s+(\d{2}\/\d{2}\/\d{4})\s*,?\s*(?:nao\s+ok|nok)$/);
if (matchDesvioAbrir) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  return output({ tipo: 'desvio_abrir', dia: Number(matchDesvioAbrir[1]), tanque: matchDesvioAbrir[2].toUpperCase(),
    navio: (matchDesvioAbrir[3] || '').toUpperCase(), dataColeta: matchDesvioAbrir[4], numero: numeroRemetente, nomeContato });
}

// Resultado (pergunta antes): "desvio do drop d5 tanque 45 confirmou em 13 e 25 graus" / "... não confirmou"
const matchDesvioRes = ajudaBusca.match(/^desvios?\s+(?:do\s+)?drops?\s+d\s*(5|10|15)\s+(?:do\s+)?tanques?\s+([a-z0-9]+)(?:\s+(?:do\s+)?navio\s+(.+?))?(?:\s*,?\s*(?:data|coleta)(?:\s+da\s+coleta)?\s+(\d{2}\/\d{2}\/\d{4}))?\s*,?\s*(nao\s+confirmou|confirmou\b(.*))$/);
if (matchDesvioRes) {
  const bloqueio = bloqueadoConsultor();
  if (bloqueio) return bloqueio;
  let temps = [];
  if (!/^nao/.test(matchDesvioRes[5])) {
    const resto = matchDesvioRes[6] || '';
    const numeros = [...resto.matchAll(/\d+/g)].map(m => Number(m[0]));
    temps = [...new Set(numeros)].sort((a, b) => a - b);
    if (!temps.length || temps.some(t => ![7, 13, 25].includes(t))) {
      return output({ tipo: 'erro_coleta', numero: numeroRemetente, nomeContato,
        textoResposta: '❌ Temperaturas do desvio: 7, 13 ou 25 °C. Ex.: desvio do drop d5 tanque 45 confirmou em 13 e 25 graus (ou: não confirmou)' });
    }
  }
  return output({ tipo: 'desvio_resultado', dia: Number(matchDesvioRes[1]), tanque: matchDesvioRes[2].toUpperCase(),
    navio: (matchDesvioRes[3] || '').toUpperCase(), dataColeta: matchDesvioRes[4] || '', temps, numero: numeroRemetente, nomeContato });
}

// Consultas: "quais últimos desvios de drops do tanque 45?" / "quais desvios estão abertos?"
const matchDesvioTanque = ajudaBusca.match(/^(?:quais\s+)?(?:os\s+)?(?:ultimos?\s+)?desvios?\s+(?:de\s+drops?\s+)?(?:(?:relacionados?|ligados?)\s+(?:ao?|com\s+o)\s+|do\s+|dos\s+)?tanques?\s+([a-z0-9]+)(?:\s+(?:do\s+)?navio\s+(.+))?$/);
if (matchDesvioTanque) {
  return output({ tipo: 'consulta_desvios', modo: 'tanque', tanque: matchDesvioTanque[1].toUpperCase(),
    navio: (matchDesvioTanque[2] || '').toUpperCase(), numero: numeroRemetente, nomeContato });
}
if (/^(?:quais\s+)?(?:os\s+)?desvios?(?:\s+de\s+drops?)?\s+(?:estao\s+|em\s+)?(?:abertos?|em\s+confirmacao|confirmacao)$/.test(ajudaBusca)) {
  return output({ tipo: 'consulta_desvios', modo: 'abertos', tanque: '', navio: '', numero: numeroRemetente, nomeContato });
