const FILTRO_TIPO_TANQUE = 'Terra';

const PRAZOS = {
  CT:   { pre: null, final: 48 },
  BL:   { pre: 72,   final: 120 },
  WORT: { pre: 120,  final: 240 }
};
const LABELS = { CT: 'CT', BL: 'BL', WORT: 'Psicrotroficos' };
const ORDEM = { CT: 0, BL: 1, WORT: 2 };

function juntarComE(lista) {
  if (lista.length === 0) return '';
  if (lista.length === 1) return lista[0];
  return lista.slice(0, -1).join(', ') + ' e ' + lista[lista.length - 1];
}

// Uma leitura conta como feita quando o Status já passou daquele estágio:
// pré-leitura → status não é mais "Aguardando Pré-Leitura"
// leitura final → status contém "conclu" (Concluído, com ou sem acento)
function leituraFeita(estagio, status) {
  const s = (status || '').toLowerCase();
  if (estagio === 'pre') return s !== '' && !s.includes('aguardando pr');
  return s.includes('conclu');
}

const linhasFiltradas = rows.filter(r => r['Tipo Tanque'] === FILTRO_TIPO_TANQUE);

const grupos = {};
function adicionarAoGrupo(estagio, r) {
  const subAnalise = r['Sub-Analise'];
  const tipoFrasco = r['Tipo Frasco'];
  const navio = r['Navio'] || '';
  const chave = `${subAnalise}|${estagio}|${tipoFrasco}`;

  if (!grupos[chave]) {
    grupos[chave] = {
      subAnalise,
      tipoFrasco,
      prazoHoras: estagio === 'pre' ? PRAZOS[subAnalise].pre : PRAZOS[subAnalise].final,
      tanques: {} // chave: "navio|tanque" → { navio, tanque, feita }
    };
  }

  // Um tanque aparece uma vez só por grupo (WORT Profundidade + Superfície viram 1 item).
  // Ele só ganha ✅ quando TODAS as linhas dele naquele grupo estiverem feitas.
  const feita = leituraFeita(estagio, r['Status']);
  const idTanque = `${navio}|${r['Tanque']}`;
  const atual = grupos[chave].tanques[idTanque];
  if (atual) {
    atual.feita = atual.feita && feita;
  } else {
    grupos[chave].tanques[idTanque] = { navio, tanque: r['Tanque'], feita };
  }
}

linhasFiltradas.forEach(r => {
  if (r['Data Pre-Leitura'] === hojeStr) adicionarAoGrupo('pre', r);
  if (r['Data Leitura Final'] === hojeStr) adicionarAoGrupo('final', r);
});

const chavesOrdenadas = Object.keys(grupos).sort((a, b) => {
  const ga = grupos[a], gb = grupos[b];
  if (ORDEM[ga.subAnalise] !== ORDEM[gb.subAnalise]) return ORDEM[ga.subAnalise] - ORDEM[gb.subAnalise];
  return ga.prazoHoras - gb.prazoHoras;
});

let totalItens = 0, totalFeitos = 0;

const linhasResposta = chavesOrdenadas.map(chave => {
  const g = grupos[chave];
  const semNavio = [];
  const porNavio = {};
  Object.values(g.tanques).forEach(t => {
    totalItens++;
    if (t.feita) totalFeitos++;
    const rotulo = t.feita ? `${t.tanque} ✅` : t.tanque;
    if (t.navio) (porNavio[t.navio] ??= []).push(rotulo);
    else semNavio.push(rotulo);
  });
  const partes = [...semNavio];
  Object.entries(porNavio).forEach(([nome, lista]) => {
    partes.push(`${juntarComE(lista)} NAVIO ${nome}`);
  });
  return `${LABELS[g.subAnalise]} (${g.prazoHoras}hrs) Tanques ${juntarComE(partes)} analise ${g.tipoFrasco}`;
});

const texto = linhasResposta.length
  ? `${linhasResposta.join('\n')}\n\n✅ = lido (${totalFeitos} de ${totalItens})`
  : `Nenhuma análise de tanque terra sai hoje (${hojeStr}).`;

return [{ json: { textoResposta: texto } }];

