parameters.jsCode:
// Monta o relatório do dia no formato do relatório oficial de microbiologia.
// Toda linha aparece, mesmo vazia ("-"), na ordem da planilha.
const rows = $input.all().map(i => i.json).filter(r => r.linha);
const item = $('Interpretar comando').first().json;
const hoje = new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });

const LINHAS_ANALISE = ['C.T 48h', 'B.L 72h', 'B.L 120h', 'Psicrotróficos 120h', 'Psicrotróficos 240h'];
const SECOES = [
  ['Normal', 'AMOSTRA NORMAL', LINHAS_ANALISE],
  ['Stress', 'AMOSTRA STRESS', LINHAS_ANALISE],
  ['Drops',  'DROPS',          ['Drop 5', 'Drop 10', 'Drop 15']]
];
const TITULOS = { 'Tank farm': 'NFC — Tank farm', 'Navio': 'NFC — Navio' };
const blocos = item.blocoFiltro ? [item.blocoFiltro] : ['Tank farm', 'Navio'];

const rotulo = r => (r.lido ? `${r.tanque} ✅` : r.tanque);

// Tank farm: "37 ✅, 41". Navio: "O.SUN 156 (1A ✅, 1F); O.SKY 133 (2P)".
function celula(lista, bloco) {
  if (lista.length === 0) return '-';
  if (bloco === 'Tank farm') return lista.map(rotulo).join(', ');
  const porNavio = {};
  lista.forEach(r => (porNavio[r.navio || 'sem navio'] ??= []).push(rotulo(r)));
  return Object.entries(porNavio).map(([navio, tanques]) => `${navio} (${tanques.join(', ')})`).join('; ');
}

let total = 0, lidos = 0;
const partes = [`📋 *Relatório do dia ${hoje}*`];

for (const bloco of blocos) {
  partes.push('', `*${TITULOS[bloco]}*`);
  for (const [amostra, titulo, linhas] of SECOES) {
    partes.push('', titulo);
    for (const linha of linhas) {
      const lista = rows.filter(r => r.bloco === bloco && r.amostra === amostra && r.linha === linha);
      total += lista.length;
      lidos += lista.filter(r => r.lido).length;
      partes.push(`${linha}: ${celula(lista, bloco)}`);
    }
    // TAB do tank farm entra na fase B (docs/concentrado.md)
    if (amostra === 'Drops' && bloco === 'Tank farm') partes.push('TAB: -');
  }
}

partes.push('', total ? `✅ = lido (${lidos} de ${total})` : 'Nenhuma leitura prevista para hoje.');

return [{ json: { ...item, textoResposta: partes.join('\n') } }];

// Gravação já feita no node anterior. Monta a resposta do recebimento.
const r = $input.first().json;
const item = $('Interpretar comando').first().json;

// [1,2,3,5,7,8] -> "1-3, 5, 7-8"
function compactar(lista) {
  const ns = [...lista].map(Number).sort((a, b) => a - b);
  const partes = [];
  for (let i = 0; i < ns.length; i++) {
    let j = i;
    while (j + 1 < ns.length && ns[j + 1] === ns[j] + 1) j++;
    partes.push(i === j ? `${ns[i]}` : `${ns[i]}-${ns[j]}`);
    i = j;
  }
  return partes.join(', ');
}

if (r.fabrica_cadastrada) {
  return [{ json: { ...item, textoResposta:
    `❌ O load ${item.load} (item ${item.item}) já está cadastrado com a fábrica ${r.fabrica_cadastrada}, não ${item.fabrica}. Nada foi gravado.` } }];
}

const novos = Array.isArray(r.novos) ? r.novos : [];
const repetidos = item.lotes.filter(l => !novos.includes(l));
const linhas = [`✅ Recebimento do load ${item.load} (item ${item.item}, fábrica ${item.fabrica}) registrado por ${item.nomeContato}.`, ''];
if (novos.length) linhas.push(`Lotes recebidos: ${compactar(novos)} (${novos.length})`);
if (repetidos.length) linhas.push(`Já recebidos antes (ignorados): ${compactar(repetidos)}`);
linhas.push(`Data: ${item.dataRecebimento}`);
if (!novos.length) linhas[0] = `ℹ️ Load ${item.load}: todos esses lotes já tinham sido recebidos. Nada novo foi gravado.`;

return [{ json: { ...item, textoResposta: linhas.join('\n') } }];

// Gravação já feita (ou recusada) no node anterior. Monta a resposta das compostas.
const r = $input.first().json;
const item = $('Interpretar comando').first().json;

function compactar(lista) {
  const ns = [...lista].map(Number).sort((a, b) => a - b);
  const partes = [];
  for (let i = 0; i < ns.length; i++) {
    let j = i;
    while (j + 1 < ns.length && ns[j + 1] === ns[j] + 1) j++;
    partes.push(i === j ? `${ns[i]}` : `${ns[i]}-${ns[j]}`);
    i = j;
  }
  return partes.join(',');
}

let texto;
if (Number(r.loads_encontrados) === 0) {
  texto = `❌ Load ${item.load}${item.item ? ' item ' + item.item : ''} não encontrado. Registre o recebimento primeiro.`;
} else if (Number(r.loads_encontrados) > 1) {
  texto = `❌ Existe mais de um load ${item.load}. Informe o item: compostas do load ${item.load} item 444 (1-5)(6-10)`;
} else if (r.erros) {
  texto = `❌ Nenhuma composta criada: ${r.erros}. Nada foi gravado.`;
} else {
  const ids = Array.isArray(r.ids) ? r.ids : [];
  const linhas = item.compostas.map((lotes, i) => `#${ids[i]} lotes ${compactar(lotes)}`);
  texto = `✅ ${ids.length} composta${ids.length === 1 ? '' : 's'} criada${ids.length === 1 ? '' : 's'} no load ${item.load}:\n${linhas.join('\n')}\n\nUse o número (#) nos próximos comandos, ex.: tab feito das compostas #${ids[0]}`;
}

return [{ json: { ...item, textoResposta: texto } }];

function compactar(lista, pref = '') {
  const ns = [...lista].map(Number).sort((a, b) => a - b);
  const partes = [];
  for (let i = 0; i < ns.length; i++) {
    let j = i;
    while (j + 1 < ns.length && ns[j + 1] === ns[j] + 1) j++;
    partes.push(i === j ? `${pref}${ns[i]}` : `${pref}${ns[i]}-${pref}${ns[j]}`);
    i = j;
  }
  return partes.join(',');
}
// Rótulo do teste: TAB ou Coliformes, e o nome da composta ou do lote aberto (#12.3)
const ROT = {
  TAB:        { nome: 'TAB', plural: 'TABs', etapa1: 'espalhar', feito1: 'espalhou', status1: 'Incubado' },
  COLIFORMES: { nome: 'Coliformes', plural: 'Coliformes', etapa1: 'estriar', feito1: 'estriou', status1: 'Estriado' }
};
const nomeTeste = r => {
  const pref = r.prefixo || '';
  const alvo = r.rotulo || ('load ' + r.load);
  return r.lote_filho
