    while (j + 1 < ord.length && ord[j + 1].numero === ord[j].numero + 1 && estadoDe(ord[j + 1]) === est) j++;
    const txt = txtFaixa([ord[i].numero, ord[j].numero], pref);
    out.push(est ? `${txt} ${est}` : txt);
    i = j + 1;
