      }).join(', ');
      if (leituras.length || doBloco.length) partes.push(`Desvios: ${txt || '-'}`);
      leituras.filter(d => d.resultado === 'Confirmado').forEach(d => alertasNfc.push(
        `🚨 Desvio CONFIRMADO — drop D${d.dia} do tanque ${d.tanque} (coleta ${d.coleta}) em ${tempsTxt(d.temperaturas)}`));
    }
    // TAB do tank farm, por tanque (com a data da coleta)
    if (amostra === 'Drops' && bloco === 'Tank farm') {
      const tabs = concRows.filter(r => r.bloco === 'Tank farm' && r.linha === 'TAB');
      total += tabs.length;
      lidos += tabs.filter(r => r.lido).length;
      const lista = tabs.filter(visivel);
      const txt = lista.map(r => {
        const est = estadoDe(r);
        return `${r.tanque} (coleta ${String(r.data_coleta).slice(0, 5)})${est ? ' ' + est : ''}`;
      }).join(', ');
      partes.push(`TAB: ${txt || '-'}`);
      tabs.filter(r => r.alarme).forEach(r => alertasNfc.push(`🚨 TAB POSITIVO — tanque ${r.tanque} (coleta ${String(r.data_coleta).slice(0, 5)})`));
    }
  }
  partes.push(...alertasNfc);
}

// ---------------- rodapé ----------------
const nAlarmes = partes.filter(p => p.startsWith('🚨')).length;
if (!total) {
  partes.push('', 'Nenhuma leitura prevista para hoje.');
} else if (completo) {
  partes.push('', `✅ lido: ${lidos} de ${total}.` + (lidos < total ? `\n⚠️ Ainda há ${total - lidos} leitura${total - lidos === 1 ? '' : 's'} de hoje por fazer: este relatório traz só o que já foi lido.` : ''));
  if (nAlarmes) partes.push(`🚨 ${nAlarmes} alerta${nAlarmes === 1 ? '' : 's'} acima.`);
} else {
  partes.push('', `✅ = lido (${lidos} de ${total})` + (nAlarmes ? ` · 🚨 = fora do limite ou positivo` : ''));
}

if (fin && fin.finalizado_por) partes.push(`✅ Leitura do dia finalizada por ${fin.finalizado_por} às ${fin.finalizado_as}.`);

return [{ json: { ...item, textoResposta: partes.join('\n') } }];

// Pergunta do "leitura do dia finalizada": mostra o que vai ser marcado como lido.
const r = $input.first().json;
const item = $('Interpretar comando').first().json;
const hoje = new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });
const n = (k) => Number(r[k]) || 0;

const partes = [];
if (n('nfc_terra')) partes.push(`NFC tank farm: ${n('nfc_terra')} leitura${n('nfc_terra') === 1 ? '' : 's'}`);
if (n('nfc_navio')) partes.push(`NFC navio: ${n('nfc_navio')} leitura${n('nfc_navio') === 1 ? '' : 's'}`);
if (n('drops')) partes.push(`Drops: ${n('drops')}`);
if (n('tab')) partes.push(`TAB: ${n('tab')}`);
if (n('coliformes')) partes.push(`Coliformes: ${n('coliformes')}`);

const linhas = [];
if (partes.length) {
  linhas.push(`❓ Marcar como lido tudo o que sai hoje (${hoje.slice(0, 5)})?`, partes.join(' · '));
  if (n('tab') || n('coliformes')) linhas.push('TAB e Coliformes sem crescimento ficam *Negativo*.');
  if (n('nfc_terra') || n('nfc_navio')) linhas.push('Leituras de NFC sem placa digitada ficam *<1* nas 3 placas.');
} else {
  linhas.push(`❓ Não há leitura pendente hoje (${hoje.slice(0, 5)}). Registrar a leitura do dia como finalizada?`);
}
if (n('contagens_sem_valor')) {
  linhas.push(`⚠️ C.T/B.L do concentrado: ${n('contagens_sem_valor')} resultado${n('contagens_sem_valor') === 1 ? '' : 's'} sem valor. Continuam pendentes até você digitar.`);
}
if (n('em_confirmacao')) {
  linhas.push(`ℹ️ ${n('em_confirmacao')} em confirmação não entra${n('em_confirmacao') === 1 ? '' : 'm'} (precisa do resultado).`);
}
if (r.ja_finalizado_por) linhas.push(`ℹ️ Hoje já foi finalizada por ${r.ja_finalizado_por}.`);
linhas.push('Responda *sim* ou *não*.');

const falta = n('contagens_sem_valor');
const resumo = `✅ Leitura do dia finalizada por ${item.nomeContato}. Relatório do dia: ` +
  (falta ? `todo lido, menos ${falta} resultado${falta === 1 ? '' : 's'} de C.T/B.L (digite os valores).` : 'todo lido.');

return [{ json: { ...item, salvar: true, payload: JSON.stringify({ acao: 'finalizar_dia' }), resumo,
  textoResposta: linhas.join('\n') } }];

// Pergunta antes de abrir ou fechar um desvio de drop.
const r = $input.all().map(i => i.json).find(x => x.drop_id);
const item = $('Interpretar comando').first().json;
const nomeDrop = (x) => `drop D${x.dia} do tanque ${x.tanque}${x.navio ? ' (navio ' + x.navio + ')' : ''} (coleta ${x.data_coleta})`;
const temps = (lista) => lista.map(t => `${t} °C`).join(lista.length === 2 ? ' e ' : ', ').replace(/, ([^,]*)$/, ' e $1');
const erro = (t) => [{ json: { ...item, salvar: false, payload: '{}', resumo: '', textoResposta: t } }];
const ref = `drop D${item.dia} do tanque ${item.tanque}${item.navio ? ' (navio ' + item.navio + ')' : ''}`;

if (item.tipo === 'desvio_abrir') {
  if (!r) return erro(`❌ Não achei o ${ref} da coleta ${item.dataColeta}. Confira o tanque e a data da coleta.`);
  if (r.desvio_id) return erro(`ℹ️ O ${nomeDrop(r)} já tem desvio (${r.desvio_status === 'Concluído' ? r.desvio_resultado.toLowerCase() : 'em confirmação, ler até ' + r.desvio_ler_ate}).`);
  return [{ json: { ...item, salvar: true,
    payload: JSON.stringify({ acao: 'abrir', drop_id: Number(r.drop_id) }),
    resumo: `⚠️ Desvio aberto: ${nomeDrop(r)}.\nRepetição do drop de arquivo em 7 °C, 13 °C e 25 °C. Leitura até ${r.ler_ate}.\n` +
      `Resultado: desvio do drop d${r.dia} tanque ${r.tanque} confirmou em 13 e 25 graus (ou: não confirmou)`,
    textoResposta: `❓ Drop *não ok*: abrir desvio do ${nomeDrop(r)}?\nRepetição do drop de arquivo em 7 °C, 13 °C e 25 °C, leitura até ${r.ler_ate}. Responda *sim* ou *não*.` } }];
}

// resultado
if (!r) return erro(`❌ Não achei desvio aberto para o ${ref}${item.dataColeta ? ' (coleta ' + item.dataColeta + ')' : ''}.`);
if (r.desvio_status !== 'Em confirmação') return erro(`ℹ️ O desvio do ${nomeDrop(r)} já foi fechado: ${String(r.desvio_resultado).toLowerCase()}.`);
const confirmou = item.temps.length > 0;
const textoRes = confirmou ? `CONFIRMOU em ${temps(item.temps)}` : 'NÃO CONFIRMOU';
return [{ json: { ...item, salvar: true,
  payload: JSON.stringify({ acao: 'fechar', desvio_id: Number(r.desvio_id), temps: item.temps }),
  resumo: `✅ Desvio do ${nomeDrop(r)} fechado: ${confirmou ? 'confirmou em ' + temps(item.temps) : 'não confirmado'}.`,
  textoResposta: `❓ Resultado do desvio do ${nomeDrop(r)}: *${textoRes}*? Responda *sim* ou *não*.` } }];

// Consultas de desvio (drop e tanque): últimos do tanque, ou os abertos.
const rows = $input.all().map(i => i.json).filter(r => r.kind);
const item = $('Interpretar comando').first().json;
const temps = (lista) => (lista || []).map(t => `${t} °C`).join(', ').replace(/, ([^,]*)$/, ' e $1');
const quem = (r) => `lido ${r.lido_dia}${r.resultado_por ? ' por ' + r.resultado_por : ''}`;
const situacaoDrop = (r) => r.status === 'Em confirmação'
  ? `em confirmação, ler até ${r.ler_ate}${r.atrasado ? ' ⚠️ atrasado' : ''}`
  : (r.resultado === 'Confirmado' ? `🚨 confirmou em ${temps(r.temperaturas)} (${quem(r)})` : `✅ não confirmado (${quem(r)})`);
const situacaoTanque = (r) => r.status === 'Em repetição'
  ? `em repetição${r.ler_ate ? ', leitura até ' + r.ler_ate : ''}${r.atrasado ? ' ⚠️ atrasado' : ''}`
  : (r.resultado === 'Não ok' ? `🚨 repetição não ok (${quem(r)})` : `✅ repetição ok (${quem(r)})`);
const deu = (r) => (r.contagem ? ` (deu ${r.contagem})` : '');
const alvo = item.modo === 'tanque' ? `tanque ${item.tanque}${item.navio ? ' (navio ' + item.navio + ')' : ''}` : '';
const navioDe = (r) => (r.navio ? ' (navio ' + r.navio + ')' : '');

let texto;
if (!rows.length) {
  texto = item.modo === 'tanque' ? `Nenhum desvio registrado para o ${alvo}.` : 'Nenhum desvio aberto.';
} else if (item.modo === 'tanque') {
  texto = `🧪 Últimos desvios — ${alvo}:\n` + rows.map(r => r.kind === 'drop'
    ? `Drop D${r.dia} · coleta ${r.data_coleta} · aberto ${r.aberto_dia}${r.aberto_por ? ' por ' + r.aberto_por : ''} · ${situacaoDrop(r)}`
    : `${r.analise} ${r.frasco}${deu(r)} · coleta ${r.data_coleta} · aberto ${r.aberto_dia}${r.aberto_por ? ' por ' + r.aberto_por : ''} · ${situacaoTanque(r)}`).join('\n');
} else {
  texto = '🧪 Desvios abertos:\n' + rows.map(r => r.kind === 'drop'
    ? `Tanque ${r.tanque}${navioDe(r)} drop D${r.dia} · coleta ${r.data_coleta} · ler até ${r.ler_ate}${r.atrasado ? ' ⚠️ atrasado' : ''}`
    : `Tanque ${r.tanque}${navioDe(r)} ${r.analise} ${r.frasco}${deu(r)} · coleta ${r.data_coleta} · ${situacaoTanque(r)}`).join('\n');
}

return [{ json: { ...item, textoResposta: texto } }];

// Pergunta antes de gravar as placas de uma leitura de NFC (mostra ok / não ok).
const r = $input.all().map(i => i.json).find(x => x.analise_id);
const item = $('Interpretar comando').first().json;
const erro = (t) => [{ json: { ...item, salvar: false, tipoPendencia: 'PLACAS', payload: '{}', resumo: '', textoResposta: t } }];
const onde = `do tanque ${item.tanque}${item.navio ? ' (navio ' + item.navio + ')' : ''}`;
if (!r) {
  return erro(`❌ Não achei leitura de ${item.rotulo} ${onde} (${item.frasco}) ${item.dataColeta ? 'da coleta ' + item.dataColeta : 'prevista para hoje ou atrasada'}.` +
    `\nConfira se a análise desse tanque e frasco foi registrada (ex.: *Analise do ${item.frasco.toLowerCase()} do tanque ${item.tanque}, data dd/mm/aaaa*)` +
    (item.dataColeta ? ' e a data da coleta.' : ' ou, se for de outra coleta, acrescente *coleta dd/mm/aaaa* no fim.'));
}
const txt = (p) => (p.sinal === '=' ? String(p.valor) : p.sinal + p.valor);
const contagem = item.placas.map(txt).join(', ');
const limite = r.limite === null || r.limite === undefined ? null : Number(r.limite);
const acima = item.placas.some(p => p.sinal === '>' || (limite !== null && p.sinal === '=' && p.valor > limite));
const situacao = acima ? 'não ok' : (limite === null ? 'sem limite cadastrado' : 'ok');
const marca = acima ? '🚨' : (limite === null ? 'ℹ️' : '✅');
const nome = `${item.rotulo} ${onde} (${item.frasco}), coleta ${r.data_coleta}${r.repeticao ? ', repetição' : ''}`;
const abreDesvio = acima && !r.tem_desvio && !r.repeticao;
const rotuloDesvio = `tanque ${item.tanque}${item.navio ? ' (navio ' + item.navio + ')' : ''} (${item.rotulo}, ${item.frasco})`;
const payload = {
  acao: 'placas', analise_id: Number(r.analise_id), etapa: item.etapa, placas: item.placas,
  nao_ok: abreDesvio,
  pergunta_desvio: `❓ Abrir desvio do ${rotuloDesvio}? A análise é repetida com o frasco de arquivo, em triplicata e com os mesmos prazos. Responda *sim* ou *não*.`,
  resumo_desvio: `⚠️ Desvio criado do ${rotuloDesvio}. Repetição com o frasco de arquivo, em triplicata e com os mesmos prazos.`
};
const linhas = [`❓ ${nome}: ${contagem} → ${marca} *${situacao}*.`];
if (r.prevista && !r.hoje) linhas.push(`ℹ️ Leitura prevista para ${r.prevista}.`);
if (Number(r.ja_lidas)) linhas.push('ℹ️ Essa leitura já tinha placas: os valores novos substituem os antigos.');
if (r.repeticao && acima) linhas.push('A repetição deu não ok: o desvio fecha como *não ok*.');
if (abreDesvio) linhas.push('Depois de gravar, pergunto se abre o desvio.');
linhas.push('Responda *sim* para gravar ou *não* para cancelar.');
return [{ json: { ...item, salvar: true, tipoPendencia: 'PLACAS', payload: JSON.stringify(payload),
  resumo: `✅ Gravado: ${nome}: ${contagem} → ${marca} ${situacao}.`, textoResposta: linhas.join('\n') } }];

// Repetição (reanálise) feita: só para tanque com desvio aberto (leitura acima do limite).
const rows = $input.all().map(i => i.json).filter(x => x.desvio_id);
const item = $('Interpretar comando').first().json;
const erro = (t) => [{ json: { ...item, salvar: false, tipoPendencia: 'DESVIO_TANQUE', payload: '{}', resumo: '', textoResposta: t } }];
const ROT = (x) => x.sub_analise === 'CT' ? 'C.T 48h'
  : x.sub_analise === 'BL' ? (x.etapa === 'pre' ? 'B.L 72h' : 'B.L 120h')
  : `WORT ${x.metodo === 'Superficie' ? 'Superfície' : 'Profundidade'} ${x.etapa === 'pre' ? '120h' : '240h'}`;
const CMD = (x) => x.sub_analise === 'CT' ? 'ct' : x.sub_analise === 'BL' ? (x.etapa === 'pre' ? 'bl72' : 'bl120')
  : `wort ${x.metodo === 'Superficie' ? 'superficie' : 'profundidade'} ${x.etapa === 'pre' ? '120h' : '240h'}`;
const tanque = `tanque ${item.tanque}${item.navio ? ' (navio ' + item.navio + ')' : ''}`;
const filtro = [item.rotulo, item.frasco].filter(Boolean).join(' ');
if (!rows.length) {
  return erro(`❌ O ${tanque} não tem desvio aberto${filtro ? ' no ' + filtro : ''}. A repetição só vale para leitura acima do limite.`);
}
if (rows.length > 1) {
  return erro(`❓ O ${tanque} tem ${rows.length} desvios abertos: ${rows.map(x => `${ROT(x)} ${x.frasco}`).join('; ')}. ` +
    `Diga qual. Ex.: repetição do tanque ${item.tanque} ${rows[0].frasco.toLowerCase()} ${CMD(rows[0])}`);
}
const x = rows[0];
const nome = `${ROT(x)} do ${tanque} (${x.frasco}), coleta ${x.data_coleta}`;
const leituras = [x.rep_pre && `pré-leitura ${x.rep_pre}`, x.rep_final && `leitura final ${x.rep_final}`].filter(Boolean).join(', ');
if (x.repeticao_feita) return erro(`ℹ️ A repetição do ${nome} já foi registrada. Leituras: ${leituras}.`);
return [{ json: { ...item, salvar: true, tipoPendencia: 'DESVIO_TANQUE',
  payload: JSON.stringify({ acao: 'repeticao', desvio_id: Number(x.desvio_id) }),
  resumo: `✅ Repetição feita: ${nome}, com o frasco de arquivo. Leituras: ${leituras}.`,
  textoResposta: `❓ Registrar a repetição feita do ${nome} (deu ${x.contagem || 'não ok'}), com o frasco de arquivo? Leituras: ${leituras}. Responda *sim* ou *não*.` } }];

// Bug 29: a resposta do "sim" só sai depois das gravações (os nodes BD acima rodam em fila).
const base = $('Processar sim ou não').first().json;
const nfc = $input.first().json || {};
const extra = nfc.perguntaDesvio ? '\n\n' + nfc.perguntaDesvio : '';
return [{ json: { ...base, textoResposta: (base.textoResposta || '') + extra } }];

// base64 da Evolution -> arquivo (binário "data") para o Gemini
const r = $input.first().json;
if (!r.base64) throw new Error('A Evolution não devolveu o áudio');
const tipo = String(r.mimetype || 'audio/ogg').split(';')[0];
return [{ json: {}, binary: { data: { data: r.base64, mimeType: tipo, fileName: 'audio.ogg' } } }];

// Texto do áudio: "🎤 Ouvi" para a pessoa conferir; vazio pede para repetir.
// Áudio de até 2 s (clique sem querer) só vale "sim" ou "não": nenhum comando cabe nisso, e no silêncio
// a transcrição pode inventar palavras do vocabulário.
const r = $input.first().json;
const segundos = Number($('Interpretar comando').first().json.segundos) || 0;
let t = String(r?.content?.parts?.[0]?.text ?? '').replace(/\s+/g, ' ').trim().replace(/^["“]+|["”]+$/g, '');
// resposta curta falada: "Sim, sim.", "sim, pode gravar", "não, cancela" (sem números) vira "sim" ou "não"
const palavras = t.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9 ]+/g, ' ').trim().split(/\s+/);
if (palavras.length <= 4 && !/\d/.test(t) && palavras[0] === 'sim') t = 'sim';
else if (palavras.length <= 4 && !/\d/.test(t) && palavras[0] === 'nao') t = 'não';
const simNao = /^(sim|n[aã]o)[.!]?$/i.test(t);
const vazio = !t || /^vazio\.?$/i.test(t) || (segundos <= 2 && !simNao);
return [{ json: { transcricao: vazio ? '' : t.slice(0, 500),
  textoResposta: vazio ? '🎤 Não entendi o áudio. Pode repetir ou mandar por escrito?' : `🎤 Ouvi: "${t.slice(0, 500)}"` } }];

